    # Non-ASCII tokens must not blow up hmac.compare_digest into a 500.
    resp: Any = client.get("/?token=tökén-秘密")
    assert resp.status_code == 401
    assert resp.json()["error"]["code"] == "unauthorized"
    resp2: Any = client.get("/", cookies={security.COOKIE_NAME: "tökén-秘密"})
    assert resp2.status_code == 401
    # A non-ASCII configured token still works for its exact value.
    monkeypatch.setenv("BLACKOUT_ACCESS_TOKEN", "tökén-秘密")
