def payload(action: str = "listen", reply: str = "", **extra: Any) -> Dict[str, Any]:
    data: Dict[str, Any] = {"action": action, "reply": reply, "reason": "理由", "user_asked_ai": False, "add_points": [], "expand_points": [], "add_parking": [], "add_decisions": [], "add_todos": [], "add_questions": [], "resolve_questions": [], "add_contradictions": [], "task": {"kind": "none", "instruction": ""}}
